9	const BASE_PREMIUMS = {
10	  sword: 100,
11	  amulet: 60,
12	  staff: 80,
13	  potion: 40,
14	  rune: 25,
15	  moonstone: 25,
16	} as const satisfies Record<string, number>;
17	
18	type InsurableItemType = keyof typeof BASE_PREMIUMS;
19	
20	type Item = {
21	  type: InsurableItemType;
22	};
23	
24	type QuoteStep = {
25	  op: "quote";
26	  items: Item[];
27	};
28	
29	type Customer = {
30	  yearsWithMHPCO: number;
31	};
32	
33	type Scenario = {
34	  customer: Customer;
35	  steps: QuoteStep[];
36	};
37	
38	const PROCESSING_FEE = 5;
39	const INITIAL_ASSESSMENT_SURCHARGE_PERCENT = 10;
40	
41	const percentOf = (amount: number, percent: number): number =>
42	  (amount * percent) / 100;
43	
44	// The MHPCO always rounds in its own favour: premiums (which the customer
45	// pays) go up. Payouts round down, but no test demands that yet.
46	const roundedUpInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
47	
48	const itemBasePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];
49	
50	// Three components of the same type form a "building block" priced as a unit
51	// rather than per item.
52	const BLOCK_SIZE = 3;
53	const BLOCK_BASE_PREMIUM = 60;
54	
55	const isBlockOfThreeAlike = (items: Item[]): boolean =>
56	  items.length === BLOCK_SIZE &&
57	  items.every((item) => item.type === items[0].type);
58	
59	// Only whole-policy blocks are recognised so far; a policy that merely
60	// contains a block is the next test's job.
61	const policyBasePremiumOf = (items: Item[]): number => {
62	  if (isBlockOfThreeAlike(items)) {
63	    return BLOCK_BASE_PREMIUM;
64	  }
65	
66	  return items.reduce((sum, item) => sum + itemBasePremiumOf(item), 0);
67	};
68	
69	const quote = (step: QuoteStep): QuoteResult => {
70	  const basePremium = policyBasePremiumOf(step.items);
71	  const initialAssessmentSurcharge = percentOf(
72	    basePremium,
73	    INITIAL_ASSESSMENT_SURCHARGE_PERCENT,
74	  );
75	
76	  return {
77	    premium: roundedUpInMHPCOsFavour(
78	      basePremium + initialAssessmentSurcharge + PROCESSING_FEE,
79	    ),
80	  };
81	};
82	
83	export const runScenario = (scenario: Scenario): ScenarioResult => {
84	  return { results: scenario.steps.map(quote) };
85	};
